namespace {
enum class LineOrigin : uint8_t { Start, End, Center, Edges };
struct LineTransition {
  bool active = false, targetOn = false, keepScene = false;
  LineOrigin origin = LineOrigin::Start;
  uint16_t startLevel = 0, start = 0, stop = 0;
  uint32_t startedAt = 0, duration = 0, fullDuration = 0;
};
LineTransition lines[MAX_NUM_SEGMENTS];
std::mutex lineMutex;

// The caller holds lineMutex; render callers are also protected by strip suspension.
const LineTransition* findLine(const Segment& segment) {
  for (unsigned id = 0; id < strip.getSegmentsNum() && id < MAX_NUM_SEGMENTS; id++) {
    const auto& line = lines[id];
    if (&segment == &strip.getSegment(id) && line.active && line.start == segment.start && line.stop == segment.stop
        && line.targetOn == bool(segment.on)) return &line;
  }
  return nullptr;
}

uint16_t levelAt(const LineTransition& line, uint32_t now) {
  const uint16_t target = line.targetOn ? UINT16_MAX : 0;
  const uint32_t elapsed = now - line.startedAt;
  if (!line.duration || elapsed >= line.duration) return target;
  const int32_t delta = int32_t(target) - line.startLevel;
  return line.startLevel + int64_t(delta) * elapsed / line.duration;
}

// Accept a numeric selector or a single ordinary WLED segment object. Old expanded
// API presets remain valid, but their cached scene and master fields are ignored.
bool readSegmentId(JsonVariant value, unsigned& id) {
  if (value.isNull()) return true;
  JsonVariant selector = value.is<JsonObject>() ? value["id"].as<JsonVariant>() : value;
  if (selector.isNull()) return false;
  if (!selector.is<int>()) return false;
  const int selected = selector.as<int>();
  if (selected < 0 || selected >= MAX_NUM_SEGMENTS) return false;
  id = selected;
  return true;
}

// Send the usual state notifications without starting WLED's global brightness
// transition or changing another segment's animation timer.
void publishLineState(uint8_t callMode) {
  setValuesFromFirstSelectedSeg();
  currentPreset = 0;
  interfaceUpdateCallMode = callMode;
  if (callMode != CALL_MODE_NOTIFICATION && callMode != CALL_MODE_NO_NOTIFY) notify(callMode);
  UsermodManager::onStateChange(callMode);
  stateChanged = false;
}
}

bool isSauluxLineTransition(const Segment& segment) {
  std::lock_guard<std::mutex> lock(lineMutex);
  return findLine(segment) != nullptr;
}

// Snapshot the moving boundary once per segment/frame. The interval is measured
// after physical mapping, so mirrored effects cannot duplicate or move the curtain.
SauluxLineMask getSauluxLineMask(const Segment& segment, unsigned length) {
  std::lock_guard<std::mutex> lock(lineMutex);
  const auto* line = findLine(segment);
  SauluxLineMask mask;
  if (!line) return mask;
  const unsigned lit = (uint32_t(levelAt(*line, millis())) * length + UINT16_MAX / 2) / UINT16_MAX;
  mask.active = true;
  switch (line->origin) {
    case LineOrigin::Start:
      mask.stop = lit;
      break;
    case LineOrigin::End:
      mask.start = length - lit;
      mask.stop = length;
      break;
    case LineOrigin::Center:
      mask.start = (length - lit) / 2;
      mask.stop = mask.start + lit;
      break;
    case LineOrigin::Edges:
      // Reveal the complement of a centered dark interval. At odd pixel counts
      // the two halves may differ by one LED, keeping every step monotonic.
      mask.start = lit / 2;
      mask.stop = mask.start + length - lit;
      mask.outside = true;
      break;
  }
  return mask;
}

// Each segment owns its timer. Ending one pass never ends a different pass or
// WLED's ordinary transition. No segment vector is accessed from this loop.
void handleSauluxLineTransitions() {
  bool changed = false;
  {
    std::lock_guard<std::mutex> lock(lineMutex);
    const uint32_t now = millis();
    for (auto& line : lines) if (line.active && (!bri || uint32_t(now - line.startedAt) >= line.duration)) {
      line.active = false;
      changed = true;
    }
  }
  if (changed) strip.trigger();
}

// Ordinary controls override their segment. A keep-scene pass accepts live color
// and brightness updates while retaining its boundary; master OFF and geometry
// changes still override it. This lets an HA light expose the curtain naturally.
void cancelSauluxLineTransitions(JsonObject root) {
  std::lock_guard<std::mutex> lock(lineMutex);
  const bool powerChange = (root["on"].is<bool>() && root["on"].as<bool>() != bool(bri)) || root["on"].is<const char*>();
  const bool brightnessChange = root.containsKey("bri") && (!root["bri"].is<int>() || root["bri"].as<int>() != bri);
  if (powerChange || root.containsKey("live") || (root["rSeg"] | false)) {
    for (auto& line : lines) line.active = false;
    return;
  }
  if (brightnessChange) for (auto& line : lines) if (!line.keepScene) line.active = false;
  const auto cancelSegment = [](JsonObject segment, int fallback) {
    if (segment.isNull()) return;
    bool changesLight = false, liveControls = true;
    for (JsonPair field : segment) {
      const char* key = field.key().c_str();
      if (!strncmp(key, "id", sizeof("id")) || !strncmp(key, "sel", sizeof("sel")) || !strncmp(key, "n", sizeof("n"))) continue;
      changesLight = true;
      if (strncmp(key, "on", sizeof("on")) && strncmp(key, "bri", sizeof("bri")) && strncmp(key, "col", sizeof("col"))
          && strncmp(key, "cct", sizeof("cct")) && strncmp(key, "fx", sizeof("fx")) && strncmp(key, "pal", sizeof("pal"))
          && strncmp(key, "frz", sizeof("frz"))) liveControls = false;
    }
    if (!changesLight) return; // selecting/naming a segment is not a lighting command
    const auto cancelLine = [&](unsigned id) {
      auto& line = lines[id];
      const bool sameTarget = segment["on"].isNull() || (segment["on"].is<bool>() && segment["on"].as<bool>() == line.targetOn);
      if (!line.keepScene || !liveControls || !sameTarget) line.active = false;
    };
    const int id = segment["id"] | fallback;
    if (id >= 0 && id < MAX_NUM_SEGMENTS) cancelLine(id);
    else if (id < 0) {
      for (unsigned i = 0; i < strip.getSegmentsNum() && i < MAX_NUM_SEGMENTS; i++)
        if (strip.getSegment(i).isSelected()) cancelLine(i);
    }
  };
  JsonVariant segments = root["seg"];
  if (segments.is<JsonObject>()) cancelSegment(segments.as<JsonObject>(), -1);
  else if (segments.is<JsonArray>()) {
    int index = 0;
    for (JsonObject segment : segments.as<JsonArray>()) cancelSegment(segment, index++);
  }
}

// Apply a directional line command directly. In contrast to ordinary WLED state parsing,
// the timer and power target belong to one segment, never to master brightness.
bool applySauluxLineToggle(JsonObject root, uint8_t callMode) {
  const char* direction = root["sauluxLine"];
  if (!direction) return false;
  LineOrigin origin;
  if (strncmp(direction, "start", sizeof("start")) == 0) origin = LineOrigin::Start;
  else if (strncmp(direction, "end", sizeof("end")) == 0) origin = LineOrigin::End;
  else if (strncmp(direction, "center", sizeof("center")) == 0) origin = LineOrigin::Center;
  else if (strncmp(direction, "edges", sizeof("edges")) == 0) origin = LineOrigin::Edges;
  else return false;
  if (root.containsKey("sauluxLineKeep") && !root["sauluxLineKeep"].is<bool>()) return false;
  unsigned id = strip.getMainSegmentId();
  if (!readSegmentId(root["seg"], id) || id >= strip.getSegmentsNum() || id >= MAX_NUM_SEGMENTS) return false;
  if (root.containsKey("tt") && !root["tt"].is<int>()) return false;
  if (!root.containsKey("tt") && root.containsKey("transition") && !root["transition"].is<int>()) return false;
  const long fullTime = root["tt"] | (root["transition"] | long(transitionDelay / 100));
  if (fullTime < 0 || fullTime > 655) return false;
  auto& segment = strip.getSegment(id);
  if (!segment.isActive()) return false;
#ifndef WLED_DISABLE_2D
  if (segment.is2D()) return false;
#endif
  // Always suspend before taking the state mutex: a render in progress may need
  // that mutex. Waiting in the opposite order would deadlock an HTTP callback.
  strip.suspend();
  strip.waitForIt();
  {
    std::lock_guard<std::mutex> lock(lineMutex);
    auto& line = lines[id];
    const uint32_t now = millis();
    const bool continuing = bri && findLine(segment) && uint32_t(now - line.startedAt) < line.duration;
    const bool turnOn = continuing ? !line.targetOn : !bri || !segment.on || !segment.opacity;
    const uint16_t level = continuing ? levelAt(line, now) : (turnOn ? 0 : UINT16_MAX);
    // Reversing keeps the existing shape, even if a different direction was
    // requested. A fresh shape only starts after the current pass has finished.
    const LineOrigin anchor = continuing ? line.origin : origin;
    const bool keepScene = continuing ? line.keepScene : (root["sauluxLineKeep"] | false);
    const uint32_t fullDuration = continuing ? line.fullDuration : uint32_t(fullTime) * 100;
    const uint32_t distance = turnOn ? UINT16_MAX - level : level;
    const uint32_t duration = (fullDuration * distance + UINT16_MAX / 2) / UINT16_MAX;
    segment.startTransition(0); // finish an ordinary transition on the next frame without resetting the effect
    if (!continuing && turnOn && !keepScene) {
      const auto oldTransition = strip.getTransition();
      strip.setTransition(0);
      segment.setMode(0, false);
      segment.palette = 0;
      segment.setOpacity(255);
      segment.setColor(0, segment.getLightCapabilities() & 2 ? RGBW32(0, 0, 0, 255) : RGBW32(255, 255, 255, 0));
      segment.setColor(1, 0);
      segment.setColor(2, 0);
      if (segment.mirror) segment.markForReset();
      segment.reverse = segment.mirror = segment.freeze = false;
      strip.setTransition(oldTransition);
    } else if (!continuing && turnOn && !segment.opacity) {
      // A zero-opacity scene is OFF too; restore a visible level while keeping color.
      segment.setOpacity(255);
    }
    if (!bri) {
      // Restore master power without waking other segments whose ON flags were
      // left set when the master was turned off.
      for (unsigned i = 0; i < strip.getSegmentsNum(); i++) if (i != id) strip.getSegment(i).on = false;
      for (auto& previous : lines) previous.active = false;
      bri = briLast ? briLast : 128;
      transitionActive = false;
      if (jsonTransitionOnce) strip.setTransition(transitionDelay);
      jsonTransitionOnce = false;
      applyFinalBri();
    }
    segment.on = turnOn;
    line.start = segment.start;
    line.stop = segment.stop;
    line.origin = anchor;
    line.keepScene = keepScene;
    line.targetOn = turnOn;
    line.startLevel = level;
    line.startedAt = now;
    line.duration = duration;
    line.fullDuration = fullDuration;
    line.active = duration > 0;
    nightlightActive = false;
  }
  strip.resume();
  strip.trigger();
  publishLineState(callMode);
  return true;
}
